<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { LayoutDashboard, Warehouse, Cylinder, FlaskConical, RadioTower, Bell, SlidersHorizontal, ClipboardList, ChartNoAxesCombined, UsersRound, BookOpen, Settings2, Search, Menu, X, ArrowUpRight, ArrowRight, ChevronDown, Plus, Activity, Thermometer, Droplets, HeartPulse, Wifi, WifiOff, CheckCheck, Clock3, LogOut, ShieldCheck, Download, CircleHelp, CalendarDays, CircleAlert, MapPin, RefreshCw, ScanLine, Check, CircleDot, Grape, Leaf, ChevronRight, LockKeyhole, UserRound, Server, AlertTriangle, Cable, Wine, Gauge, PencilLine, Filter, Play, Pause, RotateCcw, Layers2 } from 'lucide-vue-next'
import TrendChart from './components/TrendChart.vue'
import RecordForm from './components/RecordForm.vue'
import { api, auth, downloadCsv } from './api.js'

const nav=[
  {group:'ESPACIO DE TRABAJO',items:[{id:'inicio',label:'Vista general',icon:LayoutDashboard},{id:'bodegas',label:'Bodegas y cubas',icon:Warehouse},{id:'fermentaciones',label:'Fermentaciones',icon:FlaskConical},{id:'dispositivos',label:'Dispositivos IoT',icon:RadioTower}]},
  {group:'OPERACIÓN Y CONTROL',items:[{id:'alertas',label:'Centro de alertas',icon:Bell},{id:'perfiles',label:'Perfiles y umbrales',icon:SlidersHorizontal},{id:'bitacora',label:'Bitácora',icon:ClipboardList}]},
  {group:'GESTIÓN',items:[{id:'reportes',label:'Reportes',icon:ChartNoAxesCombined},{id:'usuarios',label:'Usuarios y permisos',icon:UsersRound},{id:'catalogos',label:'Catálogos',icon:Layers2}]}
]
const titles={inicio:['Vista general','Una lectura clara de cada fermentación.'],bodegas:['Bodegas y cubas','Tus instalaciones, inventario y capacidad disponible.'],fermentaciones:['Fermentaciones','Seguimiento completo de cada proceso.'],dispositivos:['Dispositivos IoT','Inventario y asignaciones de la red de sensores.'],alertas:['Centro de alertas','Desviaciones que requieren atención.'],perfiles:['Perfiles y umbrales','Rangos definidos por variedad y bodega.'],bitacora:['Bitácora','Historial trazable de intervenciones.'],reportes:['Reportes','Datos para analizar el comportamiento de cada lote.'],usuarios:['Usuarios y permisos','Responsabilidades y acceso por bodega.'],catalogos:['Catálogos de referencia','Variedades, materiales y modelos disponibles.']}
const page=ref('inicio'), sideOpen=ref(false), mode=ref('loading'), loading=ref(true), busy=ref(false), error=ref(''), notice=ref(''), search=ref(''), selectedBodega=ref('all'), selectedFermentation=ref(1), selectedMetric=ref('temp_mosto'), modal=ref(''), alertToResolve=ref(null), activeAlertFilter=ref('pendiente'), showClosed=ref(false), showCubaTab=ref('cubas'), isLoggedIn=ref(false), loginEmail=ref(''), loginPassword=ref(''), loginError=ref('')
const data=ref({bodegas:[],cubas:[],dispositivos:[],asignaciones:[],perfiles:[],fermentaciones:[],alertas:[],intervenciones:[],lecturas:[],estados_nodo:[],cepas:[],materiales:[],modelos:[],usuarios:[],usuarios_bodega:[],roles:[],empresas:[],umbrales:[]})
let refreshTimer
const listKeys=Object.keys(data.value)
async function loadData(silent=false){if(!silent)loading.value=true;try{const results=await Promise.all(listKeys.map(k=>api(`/${k}${k==='lecturas'?'?limit=1500':''}`).then(v=>[k,v])));data.value=Object.fromEntries(results);error.value='';if(!data.value.fermentaciones.some(f=>f.id===selectedFermentation.value))selectedFermentation.value=data.value.fermentaciones[0]?.id||0}catch(e){error.value=e.message;if(e.message.includes('Sesión')||e.message.includes('401')){isLoggedIn.value=false;auth.setToken('')}}finally{loading.value=false}}
async function boot(){try{const cfg=await api('/config');mode.value=cfg.mode;if(cfg.mode==='demo'||auth.token){isLoggedIn.value=true;await loadData()}else{isLoggedIn.value=false;loading.value=false}}catch(e){error.value='No se pudo conectar con FastAPI. Inicia el backend en el puerto 8000.';loading.value=false}
  refreshTimer=setInterval(()=>{if(isLoggedIn.value && !modal.value)loadData(true)},30000)
}
onMounted(boot);onUnmounted(()=>clearInterval(refreshTimer))
async function signIn(){busy.value=true;loginError.value='';try{const result=await api('/auth/login',{method:'POST',body:{email:loginEmail.value,password:loginPassword.value}});auth.setToken(result.access_token);isLoggedIn.value=true;await loadData()}catch(e){loginError.value=e.message}finally{busy.value=false}}
function logout(){auth.setToken('');isLoggedIn.value=false;page.value='inicio'}
function goto(id){page.value=id;sideOpen.value=false;search.value='';error.value=''}
const bodegas=computed(()=>data.value.bodegas),bodegaList=computed(()=>selectedBodega.value==='all'?bodegas.value:bodegas.value.filter(b=>b.id==selectedBodega.value))
const filteredCubas=computed(()=>data.value.cubas.filter(c=>selectedBodega.value==='all'||bodegaOfCuba(c)?.id==selectedBodega.value).filter(c=>!search.value||`${c.codigo} ${c.sector_cuba}`.toLowerCase().includes(search.value.toLowerCase())))
const filteredFerms=computed(()=>data.value.fermentaciones.filter(f=>selectedBodega.value==='all'||bodegaOfCuba(cubaFor(f))?.id==selectedBodega.value).filter(f=>showClosed.value||f.estado==='en curso').filter(f=>!search.value||`${cubaFor(f)?.codigo} ${cepaFor(f)?.nombre_variedad}`.toLowerCase().includes(search.value.toLowerCase())))
const pendingAlerts=computed(()=>data.value.alertas.filter(a=>a.estado==='pendiente').filter(a=>selectedBodega.value==='all'||bodegaOfCuba(cubaFor(fermentForAlert(a)))?.id==selectedBodega.value))
const visibleAlerts=computed(()=>data.value.alertas.filter(a=>activeAlertFilter.value==='todas'||a.estado===activeAlertFilter.value).filter(a=>selectedBodega.value==='all'||bodegaOfCuba(cubaFor(fermentForAlert(a)))?.id==selectedBodega.value).sort((a,b)=>severityOrder(a.severidad)-severityOrder(b.severidad)||new Date(b.timestamp)-new Date(a.timestamp)))
const activeFerms=computed(()=>data.value.fermentaciones.filter(f=>f.estado==='en curso').filter(f=>selectedBodega.value==='all'||bodegaOfCuba(cubaFor(f))?.id==selectedBodega.value))
const activeCubas=computed(()=>filteredCubas.value.filter(c=>c.estado_operativo==='en uso').length)
const activeDevices=computed(()=>data.value.dispositivos.filter(d=>d.estado==='activo').filter(d=>selectedBodega.value==='all'||data.value.asignaciones.some(a=>a.dispositivo_id===d.id&&a.activo&&bodegaOfCuba(data.value.cubas.find(c=>c.id===a.cuba_id))?.id==selectedBodega.value)).length)
const currentFerm=computed(()=>data.value.fermentaciones.find(f=>f.id===Number(selectedFermentation.value)))
const currentReadings=computed(()=>data.value.lecturas.filter(r=>r.fermentacion_id===Number(selectedFermentation.value)&&r.lectura_valida!==false).sort((a,b)=>new Date(a.timestamp)-new Date(b.timestamp)))
const lastReading=computed(()=>currentReadings.value.at(-1))
const currentProfile=computed(()=>currentFerm.value?data.value.perfiles.find(p=>p.id===currentFerm.value.perfil_id):null)
const override=computed(()=>data.value.umbrales.find(u=>u.fermentacion_id===selectedFermentation.value))
const lastReadingIsStale=computed(()=>mode.value!=='demo'&&lastReading.value&&Date.now()-new Date(lastReading.value.timestamp).getTime()>30*60*1000)
const activeLower=computed(()=>{if(selectedMetric.value==='temp_mosto')return override.value?.temp_min??currentProfile.value?.temp_min??null;if(selectedMetric.value==='ph')return override.value?.ph_min??currentProfile.value?.ph_min??null;return null})
const activeUpper=computed(()=>{if(selectedMetric.value==='temp_mosto')return override.value?.temp_max??currentProfile.value?.temp_max??null;if(selectedMetric.value==='ph')return override.value?.ph_max??currentProfile.value?.ph_max??null;return null})
const chartMetrics=[{key:'temp_mosto',label:'Temperatura',unit:'°C'},{key:'brix',label:'Grados Brix',unit:'°Bx'},{key:'ph',label:'pH',unit:''},{key:'densidad_sg',label:'Densidad',unit:'g/mL'}]
const metricMeta=computed(()=>chartMetrics.find(m=>m.key===selectedMetric.value))
function nameOf(kind,id,key='nombre'){return data.value[kind]?.find(v=>v.id===Number(id))?.[key]||'—'}
function cubaFor(f){return data.value.cubas.find(c=>c.id===f?.cuba_id)}
function bodegaOfCuba(c){return data.value.bodegas.find(b=>b.id===c?.bodega_id)}
function cepaFor(f){const p=data.value.perfiles.find(p=>p.id===f?.perfil_id);return data.value.cepas.find(c=>c.id===p?.cepa_id)}
function fermentForAlert(a){return data.value.fermentaciones.find(f=>f.id===a?.fermentacion_id)}
function readFor(f){return data.value.lecturas.filter(r=>r.fermentacion_id===f.id&&r.lectura_valida!==false).at(-1)}
function nodeFor(device){return data.value.estados_nodo.find(n=>n.dispositivo_id===device.id)}
function assignedCuba(device){const a=data.value.asignaciones.find(x=>x.dispositivo_id===device.id&&x.activo);return data.value.cubas.find(c=>c.id===a?.cuba_id)}
function severityOrder(x){return {critica:0,'crítica':0,alta:1,media:2,baja:3}[x]??4}
function niceDate(v){if(!v)return 'Sin registro';return new Date(v).toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'})}
function niceTime(v){if(!v)return '—';return new Date(v).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}
function numeric(v,d=1){return v===undefined||v===null?'—':Number(v).toLocaleString('es-CL',{minimumFractionDigits:d,maximumFractionDigits:d})}
function clsStatus(s){if(['en curso','activo','disponible','resuelta','conectado'].includes(s))return 'good';if(['pendiente','alta','media','en uso','mantención','atendida'].includes(s))return 'warn';if(['critica','crítica','desconectado','inactivo','detenida','cancelada'].includes(s))return 'danger';return 'neutral'}
function labelStatus(s){return String(s||'sin datos').replaceAll('_',' ')}
function goMonitoring(f){selectedFermentation.value=f.id;goto('inicio');setTimeout(()=>document.querySelector('#monitor')?.scrollIntoView({behavior:'smooth'}),80)}
const cards=computed(()=>[{label:'Fermentaciones activas',value:activeFerms.value.length,sub:'Procesos en seguimiento',icon:FlaskConical,tone:'plum'},{label:'Cubas en operación',value:activeCubas.value,sub:'En uso actualmente',icon:Cylinder,tone:'sand'},{label:'Alertas pendientes',value:pendingAlerts.value.length,sub:'Requieren seguimiento',icon:Bell,tone:'rose'},{label:'Nodos activos',value:activeDevices.value,sub:`De ${data.value.dispositivos.length} registrados`,icon:RadioTower,tone:'sage'}])
function success(msg){notice.value=msg;setTimeout(()=>{if(notice.value===msg)notice.value=''},5000)}
async function execute(action,msg){busy.value=true;try{await action();modal.value='';await loadData(true);success(msg)}catch(e){error.value=e.message}finally{busy.value=false}}
async function attend(a){await execute(()=>api(`/alertas/${a.id}/atender`,{method:'POST'}),'Alerta marcada como atendida.')}
function resolve(a){alertToResolve.value=a;modal.value='resolver'}
async function submitResolve(v){if(!alertToResolve.value)return;await execute(()=>api(`/alertas/${alertToResolve.value.id}/resolver`,{method:'POST',body:{nota:v.nota}}),'Alerta resuelta con nota registrada.')}
async function updateCuba(c){const choices=['disponible','mantención','fuera de servicio'];const next=window.prompt(`Nuevo estado de ${c.codigo} (${choices.join(', ')}):`,c.estado_operativo);if(!next||next===c.estado_operativo)return;await execute(()=>api(`/cubas/${c.id}/estado`,{method:'PATCH',body:{estado:next}}),'Estado de cuba actualizado.')}
async function unassign(d){const a=data.value.asignaciones.find(x=>x.dispositivo_id===d.id&&x.activo);if(!a||!window.confirm(`¿Desasignar ${d.mac_address} de ${assignedCuba(d)?.codigo}?`))return;await execute(()=>api(`/asignaciones/${a.id}/desasignar`,{method:'POST'}),'Dispositivo desasignado; el historial se conserva.')}
async function closeFerm(f,state){if(!confirm(`¿Confirmas ${state} la fermentación de ${cubaFor(f)?.codigo}?`))return;await execute(()=>api(`/fermentaciones/${f.id}/cerrar`,{method:'POST',body:{estado:state}}),`Fermentación ${state}.`)}
async function createRecord(payload){const kind=modal.value;const extra={};
 if(kind==='fermentaciones'&&payload.fecha_estimada_fin)payload.fecha_estimada_fin=new Date(payload.fecha_estimada_fin).toISOString();if(kind==='bodegas')extra.empresa_id=data.value.empresas[0]?.id||1;if(kind==='dispositivos')extra.empresa_id=data.value.empresas[0]?.id||1;if(kind==='intervenciones')extra.usuario_id=data.value.usuarios[0]?.id||1;
 if(kind==='fermentaciones'){extra.estado='en curso';extra.fecha_inicio=new Date().toISOString();}
 await execute(()=>api(`/${kind}`,{method:'POST',body:{data:{...payload,...extra}}}),'Registro guardado correctamente.')}
const option=(rows,key='nombre')=>rows.map(v=>({value:v.id,label:v[key]||`#${v.id}`}))
const formConfig=computed(()=>{
 const f={
  empresas:{title:'Registrar empresa cliente',description:'Alta disponible exclusivamente para administradores de plataforma en un entorno real.',fields:[{key:'nomb_emp',label:'Razón social',required:true},{key:'email_emp',label:'Correo de contacto',type:'email',required:true},{key:'direccion_emp',label:'Dirección'},{key:'activo',label:'Empresa activa',type:'checkbox',default:true}]},
  bodegas:{title:'Nueva bodega',description:'Registra una instalación de la empresa.',fields:[{key:'nombre',label:'Nombre',required:true},{key:'direccion',label:'Dirección',required:true},{key:'valle_vitivinicola',label:'Valle vitivinícola',required:true},{key:'comuna',label:'Comuna',required:true},{key:'region',label:'Región',required:true}]},
  cubas:{title:'Registrar cuba',description:'Incorpora una cuba al inventario de una bodega.',fields:[{key:'codigo',label:'Código único',required:true,placeholder:'CU-007'},{key:'cap_litros',label:'Capacidad (litros)',type:'number',min:1,required:true},{key:'sector_cuba',label:'Sector',required:true},{key:'bodega_id',label:'Bodega',type:'select',options:option(bodegas.value),required:true},{key:'material_id',label:'Material',type:'select',options:option(data.value.materiales),required:true},{key:'fecha_cuba',label:'Fecha de instalación',type:'date',required:true},{key:'estado_operativo',label:'Estado inicial',type:'select',options:['disponible','mantención','fuera de servicio'].map(v=>({value:v,label:v})),default:'disponible',required:true}]},
  dispositivos:{title:'Registrar dispositivo',description:'Añade un nodo de medición al inventario.',fields:[{key:'mac_address',label:'Dirección MAC',required:true,placeholder:'AA:BB:CC:DD:EE:FF'},{key:'tipo_dispositivo',label:'Tipo',required:true,default:'multisensor'},{key:'firmware_version',label:'Versión firmware',required:true,default:'1.0.0'},{key:'modelo_id',label:'Modelo',type:'select',options:option(data.value.modelos,'modelo'),required:true},{key:'estado',label:'Estado',type:'select',options:[{value:'activo',label:'Activo'},{value:'inactivo',label:'Inactivo'},{value:'en mantención',label:'En mantención'}],default:'activo',required:true}]},
  perfiles:{title:'Nuevo perfil',description:'Define rangos ideales por variedad y bodega.',fields:[{key:'nomb_perfil',label:'Nombre del perfil',required:true,wide:true},{key:'bodega_id',label:'Bodega',type:'select',options:option(bodegas.value),required:true},{key:'cepa_id',label:'Variedad',type:'select',options:option(data.value.cepas,'nombre_variedad'),required:true},{key:'temp_min',label:'Temperatura mínima (°C)',type:'number',required:true},{key:'temp_max',label:'Temperatura máxima (°C)',type:'number',required:true},{key:'brix_caida_min_dia',label:'Caída mínima diaria °Brix',type:'number',required:true,min:0},{key:'ph_min',label:'pH mínimo',type:'number',required:true,min:0,max:14},{key:'ph_max',label:'pH máximo',type:'number',required:true,min:0,max:14},{key:'activo',label:'Perfil activo',type:'checkbox',default:true}]},
  fermentaciones:{title:'Iniciar fermentación',description:'Solo cubas disponibles y perfiles activos de la misma bodega.',fields:[{key:'cuba_id',label:'Cuba disponible',type:'select',options:option(data.value.cubas.filter(c=>c.estado_operativo==='disponible'),'codigo'),required:true},{key:'perfil_id',label:'Perfil',type:'select',options:option(data.value.perfiles.filter(p=>p.activo),'nomb_perfil'),required:true},{key:'volumen_litros',label:'Volumen (L)',type:'number',min:1,required:true},{key:'brix_inicial',label:'°Brix inicial',type:'number',required:true,min:0},{key:'brix_objetivo',label:'°Brix objetivo',type:'number',required:true,min:0},{key:'densidad_inicial_sg',label:'Densidad inicial',type:'number',min:0,required:true},{key:'fecha_estimada_fin',label:'Fecha estimada de cierre',type:'datetime-local',required:true}]},
  asignaciones:{title:'Asignar dispositivo',description:'Un dispositivo solo puede tener una asignación activa.',fields:[{key:'dispositivo_id',label:'Dispositivo libre',type:'select',required:true,options:data.value.dispositivos.filter(d=>!assignedCuba(d)).map(d=>({value:d.id,label:d.mac_address}))},{key:'cuba_id',label:'Cuba',type:'select',required:true,options:option(data.value.cubas,'codigo')}]},
  intervenciones:{title:'Nueva intervención',description:'Este registro conserva autor, fecha y hora para trazabilidad.',fields:[{key:'fermentacion_id',label:'Fermentación',type:'select',required:true,options:data.value.fermentaciones.map(f=>({value:f.id,label:`${cubaFor(f)?.codigo} · ${cepaFor(f)?.nombre_variedad||'Sin variedad'}`}))},{key:'tipo_intervencion',label:'Tipo de intervención',type:'select',required:true,options:['Adición de nutrientes','Inoculación de levadura','Control de temperatura','Remontaje','Trasiego'].map(x=>({value:x,label:x}))},{key:'dosis_aplicada',label:'Dosis aplicada',required:true,placeholder:'Ej. 2 kg o N/A'},{key:'descripcion',label:'Descripción',type:'textarea',required:true,wide:true,placeholder:'Explica qué se hizo y por qué'}]},
  usuarios_bodega:{title:'Asignar rol por bodega',description:'Las responsabilidades se definen de manera independiente por instalación.',fields:[{key:'usuario_id',label:'Usuario',type:'select',required:true,options:option(data.value.usuarios,'nomb_comp')},{key:'bodega_id',label:'Bodega',type:'select',required:true,options:option(bodegas.value)},{key:'rol_id',label:'Rol',type:'select',required:true,options:option(data.value.roles,'descripcion')}]},
  resolver:{title:'Resolver alerta',description:'Documenta qué acción permitió resolver la desviación.',fields:[{key:'nota',label:'Nota de resolución',type:'textarea',required:true,wide:true,placeholder:'Describe la corrección realizada…'}]}
 };return f[modal.value]||{fields:[]}
})
</script>
<template>
<div v-if="!isLoggedIn&&!loading" class="login-shell"><div class="login-art"><div class="login-art-top"><Leaf :size="24"/> MOSTO</div><div class="login-art-bottom"><div class="overline light">PLATAFORMA PARA BODEGAS</div><h1>El buen vino comienza con buenas decisiones.</h1><p>Un solo lugar para comprender, monitorear y cuidar cada fermentación.</p></div></div><form class="login-form" @submit.prevent="signIn"><div class="eyebrow">BIENVENIDO A MOSTO</div><h2>Inicia sesión</h2><p>Accede con la cuenta registrada por tu organización.</p><label>Correo electrónico<input type="email" v-model="loginEmail" placeholder="tu@bodega.cl" required/></label><label>Contraseña<input type="password" v-model="loginPassword" required/></label><div v-if="loginError" class="inline-error">{{loginError}}</div><button class="btn-primary" :disabled="busy">{{busy?'Ingresando…':'Ingresar al espacio de trabajo'}} <ArrowRight :size="16"/></button><small>Acceso mediante Supabase Auth. Tu empresa y permisos determinan la información visible.</small></form></div>
<div v-else class="app-shell">
  <aside class="sidebar" :class="{'mobile-visible':sideOpen}">
    <div class="brand"><div class="brand-mark"><Grape :size="27" :stroke-width="1.65"/></div><div class="brand-copy"><span>mosto<span class="brand-dot">.</span></span><small>FERMENTACIÓN INTELIGENTE</small></div><button class="mobile-sidebar-close" @click="sideOpen=false"><X :size="19"/></button></div>
    <div class="sidebar-context"><div class="side-context-icon"><Warehouse :size="18"/></div><div class="side-context-text"><span>{{data.empresas[0]?.nomb_emp||'Organización'}}</span><small>{{mode==='demo'?'Espacio de demostración':'Espacio de trabajo'}}</small></div><ChevronDown :size="15" class="sidebar-chevron"/></div>
    <nav class="nav-menu"><div v-for="grp in nav" :key="grp.group" class="nav-group"><div class="nav-group-label">{{grp.group}}</div><button v-for="item in grp.items" :key="item.id" class="nav-item" :class="{'current':page===item.id}" @click="goto(item.id)"><component :is="item.icon" :size="18" :stroke-width="1.8"/><span>{{item.label}}</span><span v-if="item.id==='alertas'&&pendingAlerts.length" class="nav-count">{{pendingAlerts.length}}</span></button></div></nav>
    <div class="sidebar-bottom"><div class="side-support"><CircleHelp :size="17"/><div><strong>Acerca de Mosto</strong><small>Proyecto APT · Capstone</small></div></div><div class="side-user"><div class="avatar">CT</div><div class="side-user-copy"><span>{{mode==='demo'?'Camila Torres':'Mi cuenta'}}</span><small>{{mode==='demo'?'Administrador · demo':'Sesión autenticada'}}</small></div><button @click="mode==='demo'?success('El modo demo no utiliza inicio de sesión.'):logout()" class="side-logout" :title="mode==='demo'?'Sesión de demostración':'Cerrar sesión'"><LogOut :size="16"/></button></div></div>
  </aside>
  <div v-if="sideOpen" class="mobile-backdrop" @click="sideOpen=false"></div>
  <main class="main-content"><header class="topbar"><div class="topbar-start"><button class="menu-button" @click="sideOpen=true"><Menu :size="22"/></button><span class="breadcrumb">Espacio de trabajo</span><ChevronRight :size="14" class="breadcrumb-chevron"/><strong>{{titles[page][0]}}</strong></div><div class="topbar-end"><span class="topbar-date"><CalendarDays :size="16"/> {{new Date().toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'})}}</span><div class="top-avatar">CT</div></div></header>
  <div v-if="mode==='demo'" class="demo-strip"><span class="demo-strip-dot"></span><strong>ENTORNO DE DEMOSTRACIÓN</strong><span>Todos los nombres, valores y lecturas son ficticios. Los cambios se reinician al reiniciar la API.</span></div>
  <div v-if="error" class="app-error"><AlertTriangle :size="17"/><span>{{error}}</span><button @click="error=''" aria-label="Cerrar aviso"><X :size="16"/></button></div>
  <div v-if="notice" class="app-notice"><Check :size="17"/>{{notice}}<button @click="notice=''" aria-label="Cerrar"><X :size="15"/></button></div>
  <div v-if="loading" class="page-loading"><RefreshCw class="rotate" :size="24"/> Cargando espacio de trabajo…</div>
  <div v-else class="page-content">
    <div class="page-head"><div><div class="eyebrow">MOSTO / {{page==='inicio'?'PANORAMA GENERAL':titles[page][0].toUpperCase()}}</div><h1>{{page==='inicio'?'Cada fermentación, bajo control.':titles[page][0]}}</h1><p>{{page==='inicio'?'Visibilidad para decidir a tiempo, calidad para cuidar cada lote.':titles[page][1]}}</p></div><div class="head-controls"><label class="select-bodega"><MapPin :size="16"/><select v-model="selectedBodega"><option value="all">Todas las bodegas</option><option v-for="b in bodegas" :key="b.id" :value="String(b.id)">{{b.nombre}}</option></select><ChevronDown :size="14"/></label><button class="refresh-button" @click="loadData()" title="Actualizar datos"><RefreshCw :size="17"/></button></div></div>
    <!-- INICIO -->
    <template v-if="page==='inicio'">
      <div class="stat-grid"><div v-for="card in cards" :key="card.label" class="stat-card"><div class="stat-top"><span>{{card.label}}</span><div class="stat-icon" :class="card.tone"><component :is="card.icon" :size="20" :stroke-width="1.75"/></div></div><div class="stat-value">{{card.value.toString().padStart(2,'0')}}</div><div class="stat-sub"><span class="stat-live-dot" :class="card.tone"></span>{{card.sub}}</div></div></div>
      <div class="overview-grid"><section class="panel ferment-panel"><div class="panel-top"><div><div class="section-kicker">OPERACIÓN ACTUAL</div><h2>Fermentaciones en seguimiento</h2><p>Procesos activos de tus bodegas</p></div><button class="text-link" @click="goto('fermentaciones')">Ver todas <ArrowUpRight :size="16"/></button></div><div v-if="!activeFerms.length" class="empty-state"><FlaskConical :size="25"/><b>No hay fermentaciones activas</b><span>Registra una fermentación para comenzar a monitorear.</span></div><div v-for="f in activeFerms.slice(0,3)" :key="f.id" class="ferment-row" @click="goMonitoring(f)"><div class="ferment-left"><div class="vessel-art"><Cylinder :size="24" :stroke-width="1.35"/></div><div><strong>{{cubaFor(f)?.codigo||'Cuba'}}</strong><small>{{cepaFor(f)?.nombre_variedad||'Variedad sin asignar'}} · {{bodegaOfCuba(cubaFor(f))?.nombre}}</small></div></div><div class="ferment-right"><div class="ferment-metric"><span>TEMP.</span><b>{{numeric(readFor(f)?.temp_mosto)}}<small> °C</small></b></div><div class="ferment-metric"><span>°BRIX</span><b>{{numeric(readFor(f)?.brix)}}</b></div><span class="status-pill good"><span></span>En curso</span><ChevronRight :size="17" class="ferment-chevron"/></div></div><div class="panel-bottom"><span><CircleDot :size="13"/> Datos actualizados desde la API</span><button @click="goto('fermentaciones')">Explorar procesos <ArrowRight :size="15"/></button></div></section>
      <section class="panel alert-panel"><div class="panel-top"><div><div class="section-kicker">ATENCIÓN REQUERIDA</div><h2>Alertas recientes</h2><p>{{pendingAlerts.length}} pendiente{{pendingAlerts.length===1?'':'s'}} de revisión</p></div><div class="alert-panel-icon"><Bell :size="19"/></div></div><div v-if="!pendingAlerts.length" class="alert-clear"><CheckCheck :size="26"/><b>Sin alertas pendientes</b><span>No se han registrado desviaciones activas.</span></div><div v-for="a in pendingAlerts.slice(0,3)" :key="a.id" class="mini-alert"><div class="severity-symbol" :class="a.severidad"><AlertTriangle :size="16"/></div><div class="mini-alert-copy"><div class="mini-alert-title"><strong>{{labelStatus(a.tipo_alerta)}}</strong><span class="severity-label" :class="a.severidad">{{a.severidad}}</span></div><p>{{cubaFor(fermentForAlert(a))?.codigo}} · {{a.mensaje}}</p><small>{{niceDate(a.timestamp)}} · {{niceTime(a.timestamp)}}</small></div></div><button class="alert-full-link" @click="goto('alertas')">Ir al centro de alertas <ArrowRight :size="16"/></button></section></div>
      <section id="monitor" class="panel monitor-panel"><div class="panel-top monitor-title"><div><div class="section-kicker">TELEMETRÍA · MONITOREO</div><h2>Evolución de la fermentación</h2><p>Lecturas válidas del dispositivo conectado a la cuba</p></div><div class="monitor-select"><select v-model.number="selectedFermentation"><option v-for="f in activeFerms" :key="f.id" :value="f.id">{{cubaFor(f)?.codigo}} · {{cepaFor(f)?.nombre_variedad}}</option></select><ChevronDown :size="16"/></div></div><div class="monitor-insights"><div><span>Última temperatura</span><strong>{{numeric(lastReading?.temp_mosto)}} <small>°C</small></strong></div><div><span>Grados Brix</span><strong>{{numeric(lastReading?.brix)}} <small>°Bx</small></strong></div><div><span>pH del mosto</span><strong>{{numeric(lastReading?.ph,2)}}</strong></div><div><span>Última lectura</span><strong class="time-value">{{lastReading?niceTime(lastReading.timestamp):'Sin datos'}}</strong></div></div><div v-if="lastReadingIsStale" class="stale-warning"><WifiOff :size="16"/> Sin datos recientes: último reporte {{niceDate(lastReading.timestamp)}} a las {{niceTime(lastReading.timestamp)}}. La gráfica muestra únicamente el historial disponible.</div><div class="chart-topbar"><div class="metric-switch"><button v-for="m in chartMetrics" :key="m.key" :class="{'selected':selectedMetric===m.key}" @click="selectedMetric=m.key">{{m.label}}</button></div><span class="chart-legend"><span></span>{{metricMeta?.label}} <i></i> Umbrales vigentes</span></div><TrendChart :readings="currentReadings" :metric="selectedMetric" :lower="activeLower" :upper="activeUpper"/><div class="monitor-footer"><div><ScanLine :size="16"/><span>{{currentReadings.length}} lecturas válidas cargadas · Modo {{mode==='demo'?'demostración':'real'}}</span></div><button @click="goto('fermentaciones')">Ver ficha del proceso <ArrowUpRight :size="15"/></button></div></section>
    </template>
    <!-- BODEGAS Y CUBAS -->
    <template v-else-if="page==='bodegas'"><div class="section-actions"><div class="tabs"><button :class="{active:showCubaTab==='cubas'}" @click="showCubaTab='cubas'">Cubas <span>{{filteredCubas.length}}</span></button><button :class="{active:showCubaTab==='bodegas'}" @click="showCubaTab='bodegas'">Bodegas <span>{{bodegaList.length}}</span></button></div><button class="btn-primary" @click="modal=showCubaTab==='cubas'?'cubas':'bodegas'"><Plus :size="17"/> {{showCubaTab==='cubas'?'Registrar cuba':'Nueva bodega'}}</button></div><div v-if="showCubaTab==='cubas'" class="panel table-panel"><div class="table-toolbar"><div class="search-box"><Search :size="17"/><input v-model="search" placeholder="Buscar por código o sector…"/></div><span>{{filteredCubas.length}} cuba(s) registrada(s)</span></div><div class="table-scroll"><table><thead><tr><th>CUBA</th><th>BODEGA / SECTOR</th><th>CAPACIDAD</th><th>MATERIAL</th><th>ESTADO</th><th></th></tr></thead><tbody><tr v-for="c in filteredCubas" :key="c.id"><td><div class="row-primary"><span class="row-icon"><Cylinder :size="18"/></span><b>{{c.codigo}}</b></div></td><td><b>{{bodegaOfCuba(c)?.nombre}}</b><small>{{c.sector_cuba}}</small></td><td>{{numeric(c.cap_litros,0)}} L</td><td>{{nameOf('materiales',c.material_id)}}</td><td><span class="status-pill" :class="clsStatus(c.estado_operativo)"><span></span>{{c.estado_operativo}}</span></td><td><button class="btn-table" @click="updateCuba(c)" :disabled="c.estado_operativo==='en uso'">Cambiar estado</button></td></tr><tr v-if="!filteredCubas.length"><td colspan="6" class="table-empty">No hay cubas para mostrar.</td></tr></tbody></table></div></div><div v-else class="bodega-grid"><div v-for="b in bodegaList" :key="b.id" class="panel bodega-card"><div class="bodega-icon"><Warehouse :size="23"/></div><h3>{{b.nombre}}</h3><div class="bodega-location"><MapPin :size="14"/> {{b.valle_vitivinicola}}, {{b.region}}</div><p>{{b.direccion}} · {{b.comuna}}</p><div class="bodega-card-bottom"><span>{{data.cubas.filter(c=>c.bodega_id===b.id).length}} cubas</span><button @click="selectedBodega=String(b.id);showCubaTab='cubas'">Ver inventario <ArrowRight :size="16"/></button></div></div></div></template>
    <!-- FERMENTACIONES -->
    <template v-else-if="page==='fermentaciones'"><div class="section-actions"><div class="tabs"><button :class="{active:!showClosed}" @click="showClosed=false">En curso</button><button :class="{active:showClosed}" @click="showClosed=true">Todas e historial</button></div><button class="btn-primary" @click="modal='fermentaciones'"><Plus :size="17"/> Iniciar fermentación</button></div><div class="ferment-grid"><div v-for="f in filteredFerms" :key="f.id" class="panel ferment-card"><div class="ferment-card-top"><span class="eyebrow">FERMENTACIÓN · #{{String(f.id).padStart(3,'0')}}</span><span class="status-pill" :class="clsStatus(f.estado)"><span></span>{{f.estado}}</span></div><div class="ferment-card-hero"><div class="vessel-big"><Cylinder :size="38" :stroke-width="1.25"/></div><div><h3>{{cubaFor(f)?.codigo}}</h3><p>{{cepaFor(f)?.nombre_variedad}}</p><small>{{bodegaOfCuba(cubaFor(f))?.nombre}}</small></div></div><div class="ferment-card-stats"><div><span>Temperatura</span><strong>{{numeric(readFor(f)?.temp_mosto)}} °C</strong></div><div><span>°Brix actual</span><strong>{{numeric(readFor(f)?.brix)}}</strong></div><div><span>Volumen</span><strong>{{numeric(f.volumen_litros,0)}} L</strong></div></div><div class="ferment-dates"><span><CalendarDays :size="14"/> Inicio {{niceDate(f.fecha_inicio)}}</span><span>Meta {{niceDate(f.fecha_estimada_fin)}}</span></div><div class="ferment-actions"><button class="btn-outline" @click="goMonitoring(f)">Monitorear <ArrowUpRight :size="15"/></button><div v-if="f.estado==='en curso'" class="close-group"><button @click="closeFerm(f,'finalizada')" title="Finalizar">Finalizar</button><button @click="closeFerm(f,'detenida')" title="Detener">Detener</button></div></div></div><div v-if="!filteredFerms.length" class="panel empty-state"><FlaskConical :size="26"/><b>No hay procesos para mostrar</b><span>Inicia una fermentación o cambia los filtros.</span></div></div></template>
    <!-- DISPOSITIVOS -->
    <template v-else-if="page==='dispositivos'"><div class="section-actions"><span class="section-muted">{{data.dispositivos.length}} equipos registrados · {{data.asignaciones.filter(x=>x.activo).length}} asignaciones activas</span><div class="actions-group"><button class="btn-outline" @click="modal='asignaciones'"><Cable :size="16"/> Asignar nodo</button><button class="btn-primary" @click="modal='dispositivos'"><Plus :size="17"/> Añadir dispositivo</button></div></div><div class="device-grid"><div v-for="d in data.dispositivos" :key="d.id" class="panel device-card"><div class="device-card-head"><div class="device-illustration"><RadioTower :size="26" :stroke-width="1.55"/></div><span class="status-pill" :class="clsStatus(d.estado)"><span></span>{{d.estado}}</span></div><span class="eyebrow">{{nameOf('modelos',d.modelo_id,'modelo')}}</span><h3>Nodo {{d.mac_address.slice(-5).replace(':','–')}}</h3><p class="device-mac">{{d.mac_address}}</p><div class="device-divider"></div><div class="device-row"><span>Asignado a</span><strong>{{assignedCuba(d)?.codigo||'Sin asignación'}}</strong></div><div class="device-row"><span>Batería</span><strong>{{nodeFor(d)?.bateria_pct===undefined?'Sin reporte':nodeFor(d)?.bateria_pct+'%'}}</strong></div><div class="device-row"><span>Señal</span><strong>{{nodeFor(d)?.rssi_dbm===undefined?'Sin reporte':nodeFor(d)?.rssi_dbm+' dBm'}}</strong></div><div class="device-row"><span>Firmware</span><strong>v{{d.firmware_version}}</strong></div><button v-if="assignedCuba(d)" class="device-unassign" @click="unassign(d)">Desasignar dispositivo <ArrowRight :size="14"/></button><div class="device-last"><component :is="nodeFor(d)?.estado_red==='conectado'?Wifi:WifiOff" :size="15"/> Último reporte: {{nodeFor(d)?niceTime(nodeFor(d).timestamp):'Sin datos'}}</div></div></div></template>
    <!-- ALERTAS -->
    <template v-else-if="page==='alertas'"><div class="section-actions"><div class="tabs"><button v-for="x in [{key:'pendiente',name:'Pendientes'},{key:'atendida',name:'Atendidas'},{key:'resuelta',name:'Resueltas'},{key:'todas',name:'Todas'}]" :key="x.key" :class="{active:activeAlertFilter===x.key}" @click="activeAlertFilter=x.key">{{x.name}}</button></div><div class="alert-status-summary"><CircleAlert :size="17"/> {{pendingAlerts.length}} sin atender</div></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>ALERTA</th><th>FERMENTACIÓN</th><th>SEVERIDAD</th><th>MEDICIÓN / LÍMITE</th><th>FECHA</th><th>ESTADO</th><th>ACCIÓN</th></tr></thead><tbody><tr v-for="a in visibleAlerts" :key="a.id"><td><div class="alert-name"><span class="severity-symbol" :class="a.severidad"><AlertTriangle :size="16"/></span><div><b>{{labelStatus(a.tipo_alerta)}}</b><small>{{a.mensaje}}</small></div></div></td><td><b>{{cubaFor(fermentForAlert(a))?.codigo}}</b><small>{{cepaFor(fermentForAlert(a))?.nombre_variedad}}</small></td><td><span class="severity-label" :class="a.severidad">{{a.severidad}}</span></td><td>{{numeric(a.valor_registrado)}} / {{numeric(a.valor_limite)}}</td><td>{{niceDate(a.timestamp)}}<small>{{niceTime(a.timestamp)}}</small></td><td><span class="status-pill" :class="clsStatus(a.estado)"><span></span>{{a.estado}}</span></td><td><button v-if="a.estado==='pendiente'" class="btn-table" @click="attend(a)">Atender</button><button v-else-if="a.estado==='atendida'" class="btn-table" @click="resolve(a)">Resolver</button><span v-else class="muted-cell" :title="a.resolucion_nota">Resuelta <Check :size="14"/></span></td></tr><tr v-if="!visibleAlerts.length"><td colspan="7" class="table-empty">No hay alertas con estos filtros.</td></tr></tbody></table></div></div></template>
    <!-- PERFILES -->
    <template v-else-if="page==='perfiles'"><div class="section-actions"><span class="section-muted">Rangos usados para detectar desviaciones y orientar al enólogo.</span><button class="btn-primary" @click="modal='perfiles'"><Plus :size="17"/> Nuevo perfil</button></div><div class="profile-grid"><div v-for="p in data.perfiles.filter(p=>selectedBodega==='all'||p.bodega_id==selectedBodega)" :key="p.id" class="panel profile-card"><div class="profile-card-head"><div class="profile-icon"><SlidersHorizontal :size="21"/></div><span class="status-pill" :class="p.activo?'good':'neutral'"><span></span>{{p.activo?'Vigente':'Inactivo'}}</span></div><div class="eyebrow">{{nameOf('cepas',p.cepa_id,'nombre_variedad')}}</div><h3>{{p.nomb_perfil}}</h3><p>{{nameOf('bodegas',p.bodega_id)}}</p><div class="profile-ranges"><div><Thermometer :size="17"/><span>Temperatura</span><strong>{{numeric(p.temp_min)}}–{{numeric(p.temp_max)}} °C</strong></div><div><Droplets :size="17"/><span>pH permitido</span><strong>{{numeric(p.ph_min,2)}}–{{numeric(p.ph_max,2)}}</strong></div><div><Activity :size="17"/><span>Caída mín. °Brix/día</span><strong>{{numeric(p.brix_caida_min_dia,2)}}</strong></div></div></div></div></template>
    <!-- BITÁCORA -->
    <template v-else-if="page==='bitacora'"><div class="section-actions"><span class="section-muted">Registros cronológicos que no se editan ni eliminan.</span><button class="btn-primary" @click="modal='intervenciones'"><Plus :size="17"/> Nueva intervención</button></div><div class="panel log-panel"><div v-if="!data.intervenciones.length" class="empty-state"><ClipboardList :size="27"/><b>Sin intervenciones registradas</b></div><div v-for="entry in [...data.intervenciones].sort((a,b)=>new Date(b.fecha_registro)-new Date(a.fecha_registro))" :key="entry.id" class="log-entry"><div class="log-rail"><span></span></div><div class="log-content"><div class="log-entry-top"><strong>{{entry.tipo_intervencion}}</strong><time>{{niceDate(entry.fecha_registro)}} · {{niceTime(entry.fecha_registro)}}</time></div><p>{{entry.descripcion}}</p><div class="log-meta"><span><Cylinder :size="14"/> {{cubaFor(data.fermentaciones.find(f=>f.id===entry.fermentacion_id))?.codigo}}</span><span><UserRound :size="14"/> {{nameOf('usuarios',entry.usuario_id,'nomb_comp')}}</span><span><Gauge :size="14"/> {{entry.dosis_aplicada}}</span></div></div></div></div></template>
    <!-- REPORTES -->
    <template v-else-if="page==='reportes'"><div class="report-layout"><section class="panel report-info"><div class="section-kicker">HISTORIAL Y ANÁLISIS</div><h2>Los datos cuentan la historia del vino.</h2><p>Consulta tendencias de fermentación y exporta mediciones para analizarlas en otras herramientas. Las opciones avanzadas de informes pertenecen a historias Should/Could.</p><div class="report-select"><label>Fermentación</label><select v-model.number="selectedFermentation"><option v-for="f in data.fermentaciones" :key="f.id" :value="f.id">{{cubaFor(f)?.codigo}} · {{cepaFor(f)?.nombre_variedad}}</option></select></div><button class="btn-primary" @click="downloadCsv(selectedFermentation).then(()=>success('Archivo CSV preparado.')).catch(e=>error=e.message)"><Download :size="17"/> Exportar lecturas CSV</button><small>La exportación CSV corresponde a HU-36 (Could).</small></section><section class="panel report-side"><div class="eyebrow">REFERENCIAS DEL PROCESO</div><div class="report-metric"><span>Fecha de inicio</span><strong>{{niceDate(currentFerm?.fecha_inicio)}}</strong></div><div class="report-metric"><span>Fin estimado</span><strong>{{niceDate(currentFerm?.fecha_estimada_fin)}}</strong></div><div class="report-metric"><span>°Brix inicial</span><strong>{{numeric(currentFerm?.brix_inicial)}}</strong></div><div class="report-metric"><span>°Brix objetivo</span><strong>{{numeric(currentFerm?.brix_objetivo)}}</strong></div><div class="report-metric"><span>Lecturas válidas cargadas</span><strong>{{currentReadings.length}}</strong></div></section></div><section class="panel report-chart"><div class="panel-top"><div><div class="section-kicker">SERIES TEMPORALES</div><h2>Evolución registrada</h2></div><div class="metric-switch"><button v-for="m in chartMetrics" :key="m.key" :class="{'selected':selectedMetric===m.key}" @click="selectedMetric=m.key">{{m.label}}</button></div></div><TrendChart :readings="currentReadings" :metric="selectedMetric" :lower="activeLower" :upper="activeUpper"/></section></template>
    <!-- USUARIOS -->
    <template v-else-if="page==='usuarios'"><div class="section-actions"><span class="section-muted">Los permisos se asignan por bodega, no globalmente.</span><div class="actions-group"><button class="btn-outline" @click="modal='empresas'"><Plus :size="16"/> Registrar empresa</button><button class="btn-primary" @click="modal='usuarios_bodega'"><Plus :size="17"/> Asignar rol</button></div></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>PERSONA</th><th>CORREO</th><th>BODEGA</th><th>ROL</th><th>ESTADO</th></tr></thead><tbody><tr v-for="ub in data.usuarios_bodega" :key="ub.id"><td><div class="row-primary"><span class="user-avatar">{{nameOf('usuarios',ub.usuario_id,'nomb_comp').split(' ').map(n=>n[0]).slice(0,2).join('')}}</span><b>{{nameOf('usuarios',ub.usuario_id,'nomb_comp')}}</b></div></td><td>{{data.usuarios.find(u=>u.id===ub.usuario_id)?.correo_elec||'—'}}</td><td>{{nameOf('bodegas',ub.bodega_id)}}</td><td><span class="role-chip">{{nameOf('roles',ub.rol_id,'descripcion')}}</span></td><td><span class="status-pill good"><span></span>Activo</span></td></tr><tr v-if="!data.usuarios_bodega.length"><td colspan="5" class="table-empty">No hay usuarios con roles asignados.</td></tr></tbody></table></div></div><div class="permission-note"><ShieldCheck :size="21"/><div><strong>Separación entre empresas (HU-37)</strong><p>En modo real, los permisos deben aplicarse también en PostgreSQL mediante políticas RLS por empresa y bodega. Ocultar botones no sustituye la autorización.</p></div></div></template>
    <!-- CATÁLOGOS -->
    <template v-else-if="page==='catalogos'"><div class="catalog-grid"><section v-for="item in [{name:'Variedades de uva',key:'cepas',text:'nombre_variedad',icon:Grape},{name:'Materiales de cuba',key:'materiales',text:'nombre',icon:Cylinder},{name:'Modelos de dispositivo',key:'modelos',text:'modelo',icon:RadioTower},{name:'Roles de usuario',key:'roles',text:'descripcion',icon:UsersRound}]" :key="item.key" class="panel catalog-card"><div class="catalog-header"><div class="catalog-icon"><component :is="item.icon" :size="22"/></div><div><h3>{{item.name}}</h3><small>{{data[item.key].length}} registros · Solo lectura</small></div></div><div v-for="v in data[item.key]" :key="v.id" class="catalog-item"><span>{{v[item.text]}}</span><Check :size="15"/></div><div v-if="!data[item.key].length" class="table-empty">Sin registros</div></section></div></template>
    <footer class="page-footer"><span><Grape :size="16"/> mosto. · Plataforma IoT para fermentación</span><span>Proyecto académico Capstone · <strong>{{mode==='demo'?'Simulación':'Conectado a Supabase'}}</strong></span></footer>
  </div></main>
  <RecordForm v-if="modal" :title="formConfig.title" :description="formConfig.description" :fields="formConfig.fields" :busy="busy" :submit-label="modal==='resolver'?'Resolver alerta':'Guardar registro'" @close="modal=''" @submit="modal==='resolver'?submitResolve($event):createRecord($event)"/>
</div>
</template>
